UPDATE TM_MEMBER_MT
SET PASS_WD = #{bcryptPassword}
WHERE LOGIN_ID = #{userId}

UPDATE TR_LOGIN_LOG
   SET LOGOUT_DT = TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
 WHERE LOGIN_ID = #{loginId}
   AND LOGIN_DT = #{loginDt}
   AND LOGOUT_DT IS NULL


UPDATE TM_MEMBER_DT
SET PWD_CH_DT = sysdate
WHERE LOGIN_ID=#{LOGIN_ID}
